(7022, '発音が一晩で上手くなる人なんていません。発音を上達させるには、継続的かつ正しい鍛錬が必要です。', 'Nobody can get perfect pronunciation overnight. To improve your pronunciation you need continuous and proper training.', 46, '{"Ja": "発音が一晩で上手くなる人なんていません。発音を上達させるには、継続的かつ正しい鍛錬が必要です。", "En": "Nobody can get perfect pronunciation overnight. To improve your pronunciation you need continuous and proper training.", "Level": 46, "SourceVocabulary": [{"SubjectId": 7022, "Characters": "鍛錬"}, {"SubjectId": 3135, "Characters": "発音"}, {"SubjectId": 2467, "Characters": "一"}, {"SubjectId": 3764, "Characters": "晩"}, {"SubjectId": 6724, "Characters": "旨い"}, {"SubjectId": 3252, "Characters": "成る"}, {"SubjectId": 2475, "Characters": "人"}, {"SubjectId": 4885, "Characters": "居る"}, {"SubjectId": 9180, "Characters": "する"}, {"SubjectId": 2571, "Characters": "正しい"}, {"SubjectId": 3154, "Characters": "必要"}], "KanjiInSentence": [{"SubjectId": 729, "Characters": "発"}, {"SubjectId": 606, "Characters": "音"}, {"SubjectId": 440, "Characters": "一"}, {"SubjectId": 958, "Characters": "晩"}, {"SubjectId": 450, "Characters": "上"}, {"SubjectId": 474, "Characters": "手"}, {"SubjectId": 444, "Characters": "人"}, {"SubjectId": 1033, "Characters": "達"}, {"SubjectId": 1632, "Characters": "継"}, {"SubjectId": 1083, "Characters": "続"}, {"SubjectId": 914, "Characters": "的"}, {"SubjectId": 488, "Characters": "正"}, {"SubjectId": 1964, "Characters": "鍛"}, {"SubjectId": 1965, "Characters": "錬"}, {"SubjectId": 655, "Characters": "必"}, {"SubjectId": 737, "Characters": "要"}], "Morphemes": [{"SubjectId": 3135, "CombinedForm": null, "surface": "発音", "conjugation_type": "*", "conjugation_form": "*", "lemma_reading": "ハツオン", "lemma": "発音", "orth": "発音", "pron": "ハツオン", "Pos1": {"Ja": "名詞", "En": "noun"}, "Pos2": {"Ja": "普通名詞", "En": "common noun"}, "Pos3": {"Ja": "サ変可能", "En": "verbal noun (suru-noun)"}}, {"SubjectId": null, "CombinedForm": null, "surface": "が", "conjugation_type": "*", "conjugation_form": "*", "lemma_reading": "ガ", "lemma": "が", "orth": "が", "pron"